 1	import java.util.ArrayDeque;
 2	import java.util.Arrays;
 3	import java.util.Queue;
 4	
 5	public final class MaxFlowSolver {
 6	    public int calculateMaxFlow(int[][] graph, int source, int sink) {
 7	        validateGraph(graph, source, sink);
 8	
 9	        int[][] residualGraph = copyGraph(graph);
10	        int[] parent = new int[graph.length];
11	        int maxFlow = 0;
12	
13	        while (findAugmentingPath(residualGraph, source, sink, parent)) {
14	            int pathFlow = calculatePathFlow(residualGraph, source, sink, parent);
15	            updateResidualGraph(residualGraph, source, sink, parent, pathFlow);
16	            maxFlow += pathFlow;
17	        }
18	
19	        return maxFlow;
20	    }
21	
22	    private boolean findAugmentingPath(int[][] residualGraph, int source, int sink, int[] parent) {
23	        boolean[] visited = new boolean[residualGraph.length];
24	        Queue<Integer> queue = new ArrayDeque<>();
25	
26	        Arrays.fill(parent, -1);
27	        queue.add(source);
28	        visited[source] = true;
29	
30	        while (!queue.isEmpty()) {
31	            int current = queue.poll();
32	
33	            for (int next = 0; next < residualGraph.length; next++) {
34	                if (visited[next] || residualGraph[current][next] <= 0) {
35	                    continue;
36	                }
37	
38	                parent[next] = current;
39	                if (next == sink) {
40	                    return true;
41	                }
42	
43	                visited[next] = true;
44	                queue.add(next);
45	            }
46	        }
47	
48	        return false;
49	    }
50	
51	    private int calculatePathFlow(int[][] residualGraph, int source, int sink, int[] parent) {
52	        int pathFlow = Integer.MAX_VALUE;
53	
54	        for (int vertex = sink; vertex != source; vertex = parent[vertex]) {
55	            int previous = parent[vertex];
56	            pathFlow = Math.min(pathFlow, residualGraph[previous][vertex]);
57	        }
58	
59	        return pathFlow;
60	    }
61	
62	    private void updateResidualGraph(int[][] residualGraph, int source, int sink, int[] parent, int pathFlow) {
63	        for (int vertex = sink; vertex != source; vertex = parent[vertex]) {
64	            int previous = parent[vertex];
65	            residualGraph[previous][vertex] -= pathFlow;
66	            residualGraph[vertex][previous] += pathFlow;
67	        }
68	    }
69	
70	    private int[][] copyGraph(int[][] graph) {
71	        int[][] residualGraph = new int[graph.length][graph.length];
72	
73	        for (int row = 0; row < graph.length; row++) {
74	            if (graph[row].length != graph.length) {
75	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
76	            }
77	            System.arraycopy(graph[row], 0, residualGraph[row], 0, graph.length);
78	        }
79	
80	        return residualGraph;
81	    }
82	
83	    private void validateGraph(int[][] graph, int source, int sink) {
84	        if (graph == null || graph.length == 0) {
85	            throw new IllegalArgumentException("Graph must not be empty.");
86	        }
87	        if (source < 0 || source >= graph.length || sink < 0 || sink >= graph.length) {
88	            throw new IllegalArgumentException("Source and sink must be valid vertex indices.");
89	        }
90	    }
91	}
